function available(campus){
  return campus.geometryHash===layer.geometryHash && campus.buildings.some(b=>b.id===layer.id);
}
export function guaApproachPath(campus,id){
  return id===layer.pathId && available(campus)?layer:null;
}
const uAt=([x,,z])=>(x-layer.origin[0])*layer.basisU[0]+(z-layer.origin[1])*layer.basisU[1];
const trianglesByU=new Map();
for(const tri of layer.treadApproach){
  const u=tri.map(uAt);
  for(let k=Math.floor(Math.min(...u));k<=Math.floor(Math.max(...u));k++){
    if(!trianglesByU.has(k))trianglesByU.set(k,[]);
    trianglesByU.get(k).push(tri);
  }
}
export function sampleGuaApron(campus,x,z){
  const dx=x-layer.origin[0],dz=z-layer.origin[1];
  const u=dx*layer.basisU[0]+dz*layer.basisU[1],v=dx*layer.basisV[0]+dz*layer.basisV[1];
  const [minU,maxU,minV,maxV]=layer.bounds;
  if(u<minU||u>maxU||v<minV||v>maxV||!available(campus))return null;
  for(const [a,b,c] of trianglesByU.get(Math.floor(u))||[]){
    const ux=b[0]-a[0],uz=b[2]-a[2],vx=c[0]-a[0],vz=c[2]-a[2];
    const det=ux*vz-uz*vx;
    if(Math.abs(det)<1e-9)continue;
    const rx=x-a[0],rz=z-a[2],s=(rx*vz-rz*vx)/det,t=(ux*rz-uz*rx)/det;
    if(s< -1e-7||t< -1e-7||s+t>1+1e-7)continue;
    const elevation=a[1]+s*(b[1]-a[1])+t*(c[1]-a[1]);
    const clearance=a[3]+s*(b[3]-a[3])+t*(c[3]-a[3]);
    return {elevation,footY:elevation+clearance,clearance};
  }
  return null;
}
